147	// Shutdown enumerates live PTY sessions in the pool and reaps each one
148	// within a bounded timeout, sending SIGTERM and escalating to SIGKILL
149	// if the process does not exit cleanly.
150	func (h *Harness) Shutdown(ctx context.Context) error {
151		const defaultTimeout = 10 * time.Second
152	
153		// Extract deadline from context or use a default timeout
154		deadline, ok := ctx.Deadline()
155		if !ok {
156			deadline = time.Now().Add(defaultTimeout)
157		}
158	
159		sessions := getLiveSessionsSnapshot()
160		if len(sessions) == 0 {
161			return nil
162		}
163	
164		// Distribute remaining time across sessions
165		remaining := time.Until(deadline)
166		if remaining <= 0 {
167			remaining = 100 * time.Millisecond
168		}
169		perSessionTimeout := remaining / time.Duration(len(sessions))
170		if perSessionTimeout < 100*time.Millisecond {
171			perSessionTimeout = 100 * time.Millisecond
172		}
173	
174		for _, s := range sessions {
175			if time.Until(deadline) <= 0 {
176				break
177			}
178			sessionCtx, cancel := context.WithTimeout(context.Background(), perSessionTimeout)
179			_ = reapSession(sessionCtx, s)
180			cancel()
181		}
182	
183		return nil
184	}
