242	var (
243		claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
244		claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
245		claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
246		claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
247		claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
248	)
249	
250	// ParseClaudeTuiModels extracts available model names from claude /model output.
251	func ParseClaudeTuiModels(text string) []string {
252		text = anthropic.StripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
253		lower := strings.ToLower(text)
254		models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
255		for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
256			if len(match) > 3 {
257				models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
258			}
259		}
260		for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
261			if len(match) > 2 {
262				models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
263			}
264		}
265		for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
266			if len(match) > 1 {
267				models = appendUniqueString(models, match[1])
268			}
269		}
270		return models
271	}
272	
273	// ParseClaudeTuiReasoningLevels extracts supported reasoning levels from help output.
274	func ParseClaudeTuiReasoningLevels(text string) []string {
275		text = anthropic.StripANSI(strings.ReplaceAll(text, "\n", " "))
276		m := claudeEffortPattern.FindStringSubmatch(text)
277		if len(m) < 2 {
278			return nil
279		}
280		parts := strings.Split(m[1], ",")
281		out := make([]string, 0, len(parts))
282		for _, part := range parts {
283			out = appendUniqueString(out, strings.TrimSpace(part))
284		}
285		return out
286	}
